<?php
/** School operations 4.8.0: common guards, exact money, fees and private endpoints. */
if(!defined('SCHOOLOS_OPERATIONS_LIBRARY')){header('Location: index.php?s=operations',true,302);exit;}
function op_schema():array{return [
 "CREATE TABLE IF NOT EXISTS op_roles(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,capability VARCHAR(30) NOT NULL,PRIMARY KEY(tenant_id,user_id,capability)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS op_notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(30) NOT NULL,body VARCHAR(1000) NOT NULL,event_key VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY event_once(tenant_id,event_key),INDEX(tenant_id,student_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function op_install():void{global $pdo;foreach(['ecosystem_links','staff','students','vehicles','hostels'] as $t)if(!op_has($t))throw new RuntimeException('Prepare the existing school ecosystem first.');if(!function_exists('pp_install')||!function_exists('fnInstall')||!function_exists('awInstall'))throw new RuntimeException('Restore existing Family, Finance and Welfare dependencies.');pp_install();fnInstall();awInstall();foreach(array_merge(op_schema(),hr_schema(),tm_schema(),bd_schema()) as $sql)$pdo->exec($sql);}
function op_has(string $table):bool{return (bool)g('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[$table]);}
function op_ready():bool{foreach(['op_roles','op_notifications','hr_employees','hr_departments','hr_recruitment','hr_items','hr_policy','hr_allowances','hr_advances','hr_payruns','hr_paylines','hr_repayments','tm_drivers','tm_routes','tm_stops','tm_assignments','tm_trips','tm_passengers','tm_gps','tm_events','bd_hostel_settings','bd_rooms','bd_beds','bd_allocations','bd_presence','bd_movements','bd_leave','bd_visitors','bd_rollcalls','bd_roll_marks','bd_events','bd_supplies','bd_supply_events','bd_meals','bd_meal_links','bd_meal_servings'] as $t)if(!op_has($t))return false;return true;}
function op_actor():array{$u=me();if(!$u||(int)($u['tenant_id']??0)<1||!in_array($u['role']??'',['school_admin','staff','teacher','parent','student'],true))throw new RuntimeException('A school account is required.');if(!g('SELECT id FROM users WHERE id=? AND tenant_id=? AND role=? AND active=1',[$u['id'],$u['tenant_id'],$u['role']]))throw new RuntimeException('Account no longer active.');return $u;}
function op_can(array $u,string $cap):bool{return $u['role']==='school_admin'||(in_array($u['role'],['staff','teacher'],true)&&op_has('op_roles')&&(bool)g('SELECT user_id FROM op_roles WHERE tenant_id=? AND user_id=? AND capability=?',[$u['tenant_id'],$u['id'],$cap]));}
function op_need(array $u,string $cap):void{if(!op_can($u,$cap))throw new RuntimeException('This operation requires '.$cap.' access.');}
function op_text(string $key,int $max=2000,bool $required=false):string{$v=$_POST[$key]??'';if(!is_string($v))throw new RuntimeException('Invalid '.$key.'.');$v=trim($v);if(mb_strlen($v)>$max||($required&&$v===''))throw new RuntimeException('Check '.$key.'.');return $v;}
function op_id(string $key):int{$v=$_POST[$key]??0;if(!is_scalar($v)||!preg_match('/^\d+$/D',(string)$v))throw new RuntimeException('Invalid ID.');return (int)$v;}
function op_money(string $v,bool $zero=false):int{if(!preg_match('/^\d{1,9}(?:\.\d{1,2})?$/D',$v))throw new RuntimeException('Use a naira amount with at most two decimal places.');$p=explode('.',$v);$n=(int)$p[0]*100+(int)str_pad($p[1]??'',2,'0');if(!$zero&&$n===0)throw new RuntimeException('Amount must be positive.');return $n;}
function op_fmt(int $v):string{return 'NGN '.number_format($v/100,2);}
function op_bps(string $v):int{$n=op_money($v,true);if($n>10000)throw new RuntimeException('Percentage must be 0–100.');return $n;}
function op_percent(int $amount,int $bps):int{return intdiv($amount*$bps+5000,10000);}
function op_date(string $v):string{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new RuntimeException('Invalid date.');return $v;}
function op_time(string $v):string{$d=DateTimeImmutable::createFromFormat('!H:i',$v);if(!$d||$d->format('H:i')!==$v)throw new RuntimeException('Invalid time.');return $v;}
function op_datetime(string $v):string{$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$v);if(!$d||$d->format('Y-m-d\TH:i')!==$v)throw new RuntimeException('Invalid date/time.');return $d->format('Y-m-d H:i:s');}
function op_own(string $table,array $u,int $id):array{if(!in_array($table,['staff','students','users','vehicles','hostels','hr_employees','hr_departments','hr_recruitment','hr_items','hr_advances','hr_payruns','hr_paylines','tm_drivers','tm_routes','tm_stops','tm_trips','tm_events','bd_rooms','bd_beds','bd_allocations','bd_leave','bd_visitors','bd_rollcalls','bd_events','bd_supplies','bd_meals'],true))throw new LogicException('Invalid internal entity.');$r=q("SELECT * FROM `$table` WHERE tenant_id=? AND id=?",[$u['tenant_id'],$id])->fetch();if(!$r)throw new RuntimeException('Record unavailable.');return $r;}
function op_children(array $u):array{if(!in_array($u['role'],['student','parent'],true))return [];if($u['role']==='student'){$sid=cbStudentId((int)$u['tenant_id'],(int)$u['id']);return $sid?q('SELECT * FROM students WHERE tenant_id=? AND id=?',[$u['tenant_id'],$sid])->fetchAll():[];}return q("SELECT DISTINCT s.* FROM ecosystem_links l JOIN students s ON s.id=l.student_id AND s.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.user_id=? AND l.relation_type='parent' ORDER BY s.name",[$u['tenant_id'],$u['id']])->fetchAll();}
function op_child(array $u,int $sid):array{foreach(op_children($u) as $s)if((int)$s['id']===$sid)return $s;throw new RuntimeException('Student is not linked to this account.');}
function op_employee(array $u):array{$r=q("SELECT * FROM hr_employees WHERE tenant_id=? AND user_id=? AND status<>'exited'",[$u['tenant_id'],$u['id']])->fetchAll();if(count($r)!==1)throw new RuntimeException('Ask HR to explicitly link this account to one staff record.');return $r[0];}
function op_fee(array $u,int $student,string $kind,string $period,int $amount,string $description):int{global $pdo;if(!in_array($kind,['TM','BD','MEAL'],true)||!preg_match('/^[A-Za-z0-9_-]{1,40}$/D',$period)||$amount<=0)throw new RuntimeException('Check fee period and amount.');op_own('students',$u,$student);$ref='OPS-'.$kind.'-'.$student.'-'.$period;$old=q('SELECT id,amount_kobo FROM fn_invoices WHERE tenant_id=? AND reference=?',[$u['tenant_id'],$ref])->fetch();if($old){if((int)$old['amount_kobo']!==$amount)throw new RuntimeException('A different amount was already invoiced for this period. Review it in Finance.');return (int)$old['id'];}q('INSERT INTO fn_invoices(tenant_id,student_id,reference,description,amount_kobo,session_name) VALUES(?,?,?,?,?,?)',[$u['tenant_id'],$student,$ref,mb_substr($description,0,190),$amount,$period]);$id=(int)$pdo->lastInsertId();fnJournal((int)$u['tenant_id'],'INV-'.$id,'1100','4100',$amount,'',$description);return $id;}
function op_notify(array $u,int $sid,string $kind,string $body,string $key):void{global $pdo;$st=q('INSERT IGNORE INTO op_notifications(tenant_id,student_id,kind,body,event_key) VALUES(?,?,?,?,?)',[$u['tenant_id'],$sid,$kind,mb_substr($body,0,1000),$key]);if($st->rowCount()===1)q("INSERT INTO pp_posts(tenant_id,kind,title,body,student_id,created_by) VALUES(?,'transport',?,?,?,?)",[$u['tenant_id'],$kind==='transport'?'Transport update':'Boarding update',mb_substr($body,0,1000),$sid,$u['id']]);}
function op_action(array $u):string{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??'')))throw new RuntimeException('Security token expired.');$a=op_text('op_action',40,true);if($a==='activate'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');op_install();return 'HR, Transport and Boarding activated. Existing records preserved.';}if(!op_ready())throw new RuntimeException('Activate School Operations first.');if($a==='grant'){
 if($u['role']!=='school_admin')throw new RuntimeException('Only a school administrator can assign access.');$target=op_own('users',$u,op_id('user_id'));$cap=op_text('capability',30);if(!in_array($target['role'],['staff','teacher'],true)||!$target['active']||!in_array($cap,['hr_manager','transport_manager','boarding_manager','driver','warden'],true))throw new RuntimeException('Choose an active staff/teacher account and valid access.');if(op_text('decision',10)==='revoke')q('DELETE FROM op_roles WHERE tenant_id=? AND user_id=? AND capability=?',[$u['tenant_id'],$target['id'],$cap]);else q('INSERT IGNORE INTO op_roles(tenant_id,user_id,capability) VALUES(?,?,?)',[$u['tenant_id'],$target['id'],$cap]);audit('operations.access','user',$target['id'].' '.$cap);return 'Scoped access updated.';}
 if(str_starts_with($a,'hr_'))return hr_action($u,substr($a,3));if(str_starts_with($a,'tm_'))return tm_action($u,substr($a,3));if(str_starts_with($a,'bd_'))return bd_action($u,substr($a,3));throw new RuntimeException('Unsupported operation.');}
function op_form(string $action):void{echo '<form method="post" enctype="multipart/form-data" class="op-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="op_action" value="'.e($action).'">';}
function op_hidden(string $k,int $v):void{echo '<input type="hidden" name="'.e($k).'" value="'.$v.'">';}
function op_field(string $key,string $label,string $type='text',string $value='',bool $required=true):void{echo '<label>'.e($label);if($type==='textarea')echo '<textarea name="'.e($key).'" rows="3"'.($required?' required':'').'>'.e($value).'</textarea>';else echo '<input name="'.e($key).'" type="'.e($type).'" value="'.e($value).'"'.($type==='number'?' step="0.01"':'').($required?' required':'').'>';echo '</label>';}
function op_select(string $k,string $label,array $choices):void{echo '<label>'.e($label).'<select name="'.e($k).'" required>';foreach($choices as $v=>$text)echo '<option value="'.e($v).'">'.e($text).'</option>';echo '</select></label>';}
function op_check(string $k,string $label):void{echo '<label class="op-check"><input type="checkbox" name="'.e($k).'" value="yes">'.e($label).'</label>';}
function op_end(string $label):void{echo '<div><button class="btn">'.e($label).'</button></div></form>';}
function op_choices(array $rows,string $field='name'):array{$r=[];foreach($rows as $row)$r[$row['id']]=$row[$field].' #'.$row['id'];return $r;}
function op_table(array $rows,array $heads):void{echo '<div class="op-scroll"><table class="table"><tr>';foreach($heads as $h)echo '<th>'.e($h).'</th>';echo '</tr>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.e($v).'</td>';echo '</tr>';}echo '</table></div>';if(!$rows)echo '<p>No records yet.</p>';}
function op_card(string $title):void{echo '<section class="op-card"><h3>'.e($title).'</h3>';}
function op_render(array $u):void{
 echo '<style>.op-hero{padding:24px;border-radius:18px;background:linear-gradient(115deg,#17394d,#12766c);color:white}.op-nav{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.op-nav a{padding:10px;border:1px solid var(--line);border-radius:9px;text-decoration:none;color:var(--ink);background:var(--card-bg)}.op-card{padding:22px;margin:16px 0;border:1px solid var(--line);border-radius:15px;background:var(--card-bg)}.op-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:18px 0}.op-form label{display:grid;gap:7px}.op-form input,.op-form select,.op-form textarea{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--field-bg);color:var(--field-text);font:inherit}.op-form label:has(textarea){grid-column:1/-1}.op-form .op-check{display:flex;align-items:center}.op-check input{width:auto}.op-scroll{overflow:auto}.op-card p{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:650px){.op-form{grid-template-columns:1fr}.op-card{padding:15px}}</style><div class="op-hero"><h2>School Operations</h2><p>People, payroll, transport and boarding.</p></div>';
 if(!op_ready()){op_card('Activate School Operations');echo '<p>Back up the database first. Activation adds operational tables without deleting existing records.</p>';if($u['role']==='school_admin'){op_form('activate');op_end('Activate School Operations');}else echo '<p>Ask your school administrator to activate these modules.</p>';echo '</section>';return;}
 $area=is_string($_GET['area']??null)?$_GET['area']:'overview';if(!in_array($area,['overview','hr','transport','boarding','access'],true))$area='overview';echo '<nav class="op-nav">';foreach(['overview'=>'Overview','hr'=>'Human Resources & Payroll','transport'=>'Transport Management','boarding'=>'Hostel & Boarding','access'=>'Access controls'] as $k=>$v){if($k==='access'&&$u['role']!=='school_admin')continue;if($k==='hr'&&!in_array($u['role'],['teacher','staff','school_admin'],true))continue;echo '<a href="?s=operations&amp;area='.$k.'">'.e($v).'</a>';}echo '</nav>';
 if($area==='hr')hr_render($u);elseif($area==='transport')tm_render($u);elseif($area==='boarding')bd_render($u);elseif($area==='access'){
  if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');op_card('Assign scoped operations access');op_form('grant');op_select('user_id','Existing active staff/teacher account',op_choices(q("SELECT id,name FROM users WHERE tenant_id=? AND role IN ('staff','teacher') AND active=1 ORDER BY name",[$u['tenant_id']])->fetchAll()));op_select('capability','Access',array_combine(['hr_manager','transport_manager','boarding_manager','driver','warden'],['HR manager — private personnel/payroll','Transport manager','Boarding manager','Driver — assigned trips only','Warden — assigned hostels only']));op_select('decision','Decision',['grant'=>'Grant','revoke'=>'Revoke']);op_end('Save scoped access');op_table(q('SELECT u.name,r.capability FROM op_roles r JOIN users u ON u.id=r.user_id AND u.tenant_id=r.tenant_id WHERE r.tenant_id=? ORDER BY u.name',[$u['tenant_id']])->fetchAll(),['Account','Access']);echo '</section>';
 }else{op_card('Your operations workspace');echo '<p>Choose a module above. Private payroll is restricted to HR managers and the school administrator. Drivers and wardens see only assigned work. Staff can view their own linked records; families can view their linked children’s transport and boarding updates.</p>';foreach(op_children($u) as $s){echo '<h4>'.e($s['name']).'</h4>';op_table(q('SELECT kind,body,created_at FROM op_notifications WHERE tenant_id=? AND student_id=? ORDER BY id DESC LIMIT 50',[$u['tenant_id'],$s['id']])->fetchAll(),['Update','Message','Time']);}echo '</section>';}
}
function op_autoform(string $action,array $fields,string $button):void{op_form($action);foreach($fields as $key=>$spec){[$label,$type]=$spec;if(is_array($type))op_select($key,$label,$type);elseif($type==='check')op_check($key,$label);else op_field($key,$label,$type,(string)($spec[2]??''),(bool)($spec[3]??true));}op_end($button);}
